# Streamlit Cloud: Secrets에 OPENAI_API_KEY 등록 시 환경변수로 연결
try:
    if "OPENAI_API_KEY" in st.secrets:
        os.environ["OPENAI_API_KEY"] = st.secrets["OPENAI_API_KEY"]
except Exception:
    pass

CHROMA_DIR = "chroma_db"          # Colab에서 만든 폴더와 같아야 함
COLLECTION = "aivle_docs"         # Colab에서 만든 컬렉션과 같아야 함
# 답변 모델: gpt-6-luna (Streamlit Secrets에 LLM_MODEL을 넣으면 코드 수정 없이 교체 가능)
def _secret(name, default=""):
    try:
        return os.environ.get(name) or str(st.secrets.get(name, default))
    except Exception:
        return os.environ.get(name, default)


LLM_MODEL = _secret("LLM_MODEL", "gpt-6-luna") or "gpt-6-luna"


def make_llm(temperature=None, streaming=False):
    """모델별 호환 옵션으로 LLM 생성
    - gpt-6 계열(luna): temperature를 보내지 않고 reasoning_effort="none"으로 비용·지연을 줄임
    - 그 외 모델: 기존처럼 temperature 사용"""
    opts = {}
    if LLM_MODEL.startswith("gpt-6"):
        opts["reasoning_effort"] = "none"
    elif temperature is not None:
        opts["temperature"] = temperature
    return ChatOpenAI(model=LLM_MODEL, streaming=streaming, timeout=90, **opts)
EMB_MODEL = "text-embedding-3-small"

