def find_korean_font():
    """한글 폰트 찾기 (고정폭 Coding 폰트는 제외하고 일반 고딕 우선)"""
    from matplotlib import font_manager
    paths = [p for p in font_manager.findSystemFonts() if "coding" not in os.path.basename(p).lower()]
    for key in ["nanumgothic.ttf", "nanumbarungothic", "nanumgothic", "notosanscjk", "notosanskr",
                "malgun", "applegothic"]:
        for p in paths:
            if key in os.path.basename(p).lower() and "bold" not in os.path.basename(p).lower():
                return p
    return None


def roadmap_markdown(rm, is_applicant=False):
    md = [f"# {rm.get('title', '나의 학습 로드맵')}", "", rm.get("summary", ""), ""]
    for w in rm.get("weeks", []):
        stage = APPLICANT_STAGES[w["week"] - 1] if is_applicant else f"{w['week']}주차"
        md.append(f"## {stage} · {w.get('goal', '')}")
        for it in w.get("items", []):
            md.append(f"- **{it.get('topic')}**: {it.get('task')} ({it.get('hours')}h)")
        md.append("")
    if rm.get("tips"):
        md.append("## 선배 팁")
        md += [f"- {t}" for t in rm["tips"]]
    return "\n".join(md)


